WITH valid AS (SELECT *, CASE WHEN browser IN ('Chrome', 'Safari') THEN 'Core' ELSE 'Other' END AS browser_group FROM sessions WHERE started_at >= TIMESTAMP '2023-03-06 21:00:00' AND country IS NOT NULL) SELECT device, DATE_TRUNC('YEAR', started_at) AS year_start, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS duration_min, MAX(started_at) AS last_seen, MIN(started_at) AS first_seen, MIN(started_at) AS first_seen_2, COUNT(CASE WHEN device = 'tablet' THEN 1 END) AS tablet_count, COUNT(*) AS row_count FROM valid GROUP BY device, DATE_TRUNC('YEAR', started_at) ORDER BY tablet_count DESC NULLS LAST
